import React from "react";
import { interpolate, spring, useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type CartoonListRevealProps = Record<string, any>;

const CartoonListReveal: React.FC<CartoonListRevealProps> = ({
  backgroundColor = "#87CEEB", // Sky blue for cartoon feel
  transparentBackground = false,
  durationInSeconds = 5,
  calendarYear = "2026",
  item1Text = "🚀 Rocket Launch",
  item2Text = "🍌 Fresh Bananas",
  item3Text = "✨ Magic Sparkles",
  cardColor = "#FFFFFF",
  textColor = "#333333",
  accentColor = "#FF6B6B", // Reddish/Coral
  itemGap = 30,
}) => {
  // Load cartoonish font
  useFontLoader(["Fredoka One"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  const items = [item1Text, item2Text, item3Text];
  
  // Layout constants
  const itemHeight = height * 0.15;
  const itemWidth = width * 0.6;
  const calendarHeight = height * 0.22;
  const calendarWidth = height * 0.22; // Square based on height
  const calendarGap = height * 0.05;
  
  const totalContentHeight = calendarHeight + calendarGap + (items.length * itemHeight + (items.length - 1) * itemGap);
  const topStartY = (height - totalContentHeight) / 2;
  const listStartY = topStartY + calendarHeight + calendarGap;

  // Calendar Animations (Shows up first)
  const calSpr = spring({
    frame: frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const calBlurVal = interpolate(frame, [0, 45], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const calOpacityVal = interpolate(frame, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const calTranslateY = interpolate(calSpr, [0, 1], [50, 0]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "'Fredoka One', cursive",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div style={{ position: "relative", width: "100%", height: "100%" }}>
        
        {/* Calendar Element */}
        <div
          style={{
            position: "absolute",
            top: topStartY,
            left: (width - calendarWidth) / 2,
            width: calendarWidth,
            height: calendarHeight,
            backgroundColor: cardColor,
            borderRadius: 20,
            border: `4px solid ${textColor}`,
            boxShadow: `8px 8px 0px ${accentColor}`,
            display: "flex",
            flexDirection: "column",
            opacity: calOpacityVal,
            transform: `scale(${calSpr}) translateY(${calTranslateY}px)`,
            filter: `blur(${calBlurVal}px)`,
            transition: "none",
          }}
        >
          {/* Calendar Binder Rings */}
          <div style={{ position: "absolute", top: -15, left: "20%", width: 14, height: 30, backgroundColor: cardColor, border: `4px solid ${textColor}`, borderRadius: 10 }} />
          <div style={{ position: "absolute", top: -15, right: "20%", width: 14, height: 30, backgroundColor: cardColor, border: `4px solid ${textColor}`, borderRadius: 10 }} />

          {/* Calendar Header */}
          <div
            style={{
              width: "100%",
              height: "30%",
              backgroundColor: accentColor,
              borderBottom: `4px solid ${textColor}`,
              borderTopLeftRadius: 16,
              borderTopRightRadius: 16,
            }}
          />

          {/* Calendar Body (Year) */}
          <div
            style={{
              flex: 1,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              fontSize: calendarHeight * 0.35,
              color: textColor,
              paddingTop: 10,
            }}
          >
            {calendarYear}
          </div>
        </div>

        {/* List Items */}
        {items.map((text, index) => {
          // Stagger logic: Calendar is 0, list items start after
          const delay = (index + 1) * 20; 
          
          // Animations
          const spr = spring({
            frame: frame - delay,
            fps,
            config: { damping: 12, stiffness: 100 },
          });

          const blurVal = interpolate(
            frame,
            [delay, delay + 45],
            [20, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const opacityVal = interpolate(
            frame,
            [delay, delay + 10],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Calculate Y position starting below the calendar
          const topPos = listStartY + index * (itemHeight + itemGap);

          // Cartoon entry effect: slide up slightly + scale bounce
          const translateY = interpolate(
            spr,
            [0, 1],
            [50, 0]
          );

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                top: topPos,
                left: (width - itemWidth) / 2,
                width: itemWidth,
                height: itemHeight,
                backgroundColor: cardColor,
                borderRadius: 20,
                border: `4px solid ${textColor}`,
                boxShadow: `8px 8px 0px ${accentColor}`,
                display: "flex",
                alignItems: "center",
                justifyContent: "flex-start", // Align text left with padding
                paddingLeft: itemWidth * 0.1,
                fontSize: itemHeight * 0.4,
                color: textColor,
                opacity: opacityVal,
                transform: `scale(${spr}) translateY(${translateY}px)`,
                filter: `blur(${blurVal}px)`,
                transition: "none", // Forbidden CSS transition
              }}
            >
              {/* Bullet point / Number circle */}
              <div
                style={{
                  width: itemHeight * 0.5,
                  height: itemHeight * 0.5,
                  borderRadius: "50%",
                  backgroundColor: accentColor,
                  color: "#FFF",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  marginRight: 20,
                  border: `3px solid ${textColor}`,
                  fontSize: itemHeight * 0.25,
                }}
              >
                {index + 1}
              </div>
              {text}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default CartoonListReveal;